function fechaArch(){ var d=new Date(), p=function(n){return (n<10?'0':'')+n;}; return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate()); }
function guardarPDF(secs,titulo,msg,op){
  var tiene=secs.some(function(x){ return x.txt&&x.txt.trim(); });
  if(!tiene){ if(msg) msg.textContent='Todavía no hay nada que poner en la nota.'; return; }
  var d=null; try{ d=hacerPDF(secs,titulo,op); }catch(e){ d=null; if(window.console) console.error(e); }
  if(!d){ if(msg) msg.textContent='No se pudo crear el PDF en este navegador.'; return; }
  var nom=(op&&op.arch||'Nota')+'_'+String(REG.nombre||'paciente').replace(/[^A-Za-z0-9\u00c0-\u00ff]+/g,'_')+'_'+fechaArch()+'.pdf';
  var blob=d.output('blob');
  var tactil=!!(window.matchMedia&&matchMedia('(pointer:coarse)').matches);
  try{ var file=new File([blob],nom,{type:'application/pdf'});
    if(tactil&&navigator.canShare&&navigator.canShare({files:[file]})){ navigator.share({files:[file],title:win(titulo)}).catch(function(){}); if(msg) msg.textContent='Elija «Guardar en Archivos», «Imprimir» o envíelo.'; return; } }catch(e){}
  var u=URL.createObjectURL(blob), a=document.createElement('a'); a.href=u; a.download=nom; a.rel='noopener'; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function(){ URL.revokeObjectURL(u); },120000);
  if(msg) msg.textContent='PDF listo. Si no se abrió, búsquelo en Descargas.';
}

