var notaSel={integral:true,pronostico:true,opioides:true,nutricion:true,sedacion:true};
function noteOf(id){ if(!ready[id]) return ''; var d=frames[id].contentDocument; var el=d&&d.getElementById(NOTE_ID[id]); return el?(el.innerText||el.textContent||'').trim():''; }
function hoy(){ var d=new Date(), p=function(n){return (n<10?'0':'')+n;}; return p(d.getDate())+'/'+p(d.getMonth()+1)+'/'+d.getFullYear()+' '+p(d.getHours())+':'+p(d.getMinutes()); }
function notaSecs(){ var o=[]; META.forEach(function(m){ if(m.id==='nota'||!notaSel[m.id]) return; var t=noteOf(m.id); if(t) o.push({t:m.t,txt:t,banda:1}); }); return o; }
function buildNota(){
  var L=[], p=REG;
  L.push('NOTA MÉDICA INTEGRADA · MEDICINA PALIATIVA');
  L.push('Fecha: '+hoy());
  var id=[]; if(p.nombre) id.push(p.nombre); if(p.edad) id.push(p.edad+' años'); if(p.sexo) id.push(p.sexo==='F'?'mujer':'hombre');
  if(id.length) L.push('Paciente: '+id.join(', '));
  var an=[]; if(p.peso) an.push('peso '+p.peso+' kg'); if(p.talla) an.push('talla '+p.talla+' cm');
  if(num(p.peso)&&num(p.talla)) an.push('IMC '+r1(num(p.peso)/Math.pow(num(p.talla)/100,2)));
  var pp=pperd(); if(pp!=='') an.push('pérdida de peso '+pp+' %');
  if(an.length) L.push('Somatometría: '+an.join(', '));
  if(p.dxtxt) L.push('Diagnóstico: '+p.dxtxt);
  var lab=[]; if(p.creat){ lab.push('creatinina '+p.creat+' mg/dL'); if(num(p.edad)>=18&&p.sexo) lab.push('TFG CKD-EPI 2021 '+Math.round(ckdEpi(num(p.creat),num(p.edad),p.sexo))+' mL/min/1.73 m²'); }
  if(p.alb) lab.push('albúmina '+p.alb+' g/dL'); if(p.pcr) lab.push('PCR '+p.pcr+' mg/L'); if(p.na) lab.push('Na '+p.na+' mEq/L');
  if(p.child&&p.child!=='none') lab.push('Child-Pugh '+p.child);
  if(lab.length) L.push('Laboratorio: '+lab.join(', '));
  var n=0;
  notaSecs().forEach(function(x){ n++; L.push(''); L.push('━━ '+x.t.toUpperCase()+' ━━'); L.push(x.txt); });
  L.push(''); L.push('Dra. Gabriela Alejandra López Ortiz · Anestesiología, Medicina Paliativa y del Dolor · Céd. Prof. 6383462 · Céd. Esp. 12184347');
  return {txt:L.join('\n'),n:n};
}
