    h+='<details><summary>Ver o copiar la nota en texto (para el expediente electrónico)</summary><pre class="rx" id="notaTxt"></pre><div class="ptbtns"><button type="button" class="btn ghost" id="nCopy">Copiar texto</button></div></details>';
