function copiar(t,msg){
  function viejo(){ var ta=document.createElement('textarea'); ta.value=t; ta.setAttribute('readonly',''); ta.style.position='fixed'; ta.style.top='-1000px'; document.body.appendChild(ta); ta.select(); ta.setSelectionRange(0,t.length);
    var r=false; try{ r=document.execCommand('copy'); }catch(e){} document.body.removeChild(ta); msg.textContent=r?'Nota copiada.':'Seleccione el texto y cópielo con el menú.'; }
  try{ if(navigator.clipboard&&window.isSecureContext){ navigator.clipboard.writeText(t).then(function(){ msg.textContent='Nota copiada.'; },viejo); } else viejo(); }catch(e){ viejo(); }
}

